#nullable enable // autogenerated

using MVZ2.GameContent.Damages;
using MVZ2.Vanilla.Callbacks;
using MVZ2.Vanilla.Entities;
using MVZ2Logic;
using MVZ2Logic.Artifacts;
using MVZ2Logic.Level;
using PVZEngine.Callbacks;
using PVZEngine.Damages;

namespace MVZ2.GameContent.Artifacts
{
    [ArtifactDefinition(VanillaArtifactNames.heavyBassDrum)]
    public class HeavyBassDrum : ArtifactDefinition
    {
        public HeavyBassDrum(string nsp, string name) : base(nsp, name)
        {
            AddTrigger(VanillaLevelCallbacks.POST_PROJECTILE_HIT, PostProjectileHitCallback);
        }
        private void PostProjectileHitCallback(VanillaLevelCallbacks.PostProjectileHitParams hitParams, CallbackResult result)
        {
            var projectile = hitParams.hit.Projectile;
            if (projectile.IsHostileEntity())
                return;
            var excludeCollider = hitParams.hit.Collider;
            var level = projectile.Level;
            bool valid = false;
            var artifacts = level.GetArtifacts();
            foreach (var artifact in artifacts)
            {
                if (artifact == null)
                    continue;
                if (artifact.Definition != this)
                    continue;
                artifact.Highlight();
                valid = true;
            }
            if (valid)
            {
                projectile.SplashDamage(excludeCollider, projectile.GetCenter(), 20, projectile.GetFaction(), projectile.GetDamage() * 0.1f, new DamageEffectList(VanillaDamageEffects.MUTE));
            }
        }
    }
}
